/**
 * Get the transferability score from one role to another.
 * Returns 0 if no edge exists (score too low or pair never computed).
 */
export function getTransferability(fromSoc: string, toSoc: string): number {
  const edges = TRANSFERABILITY[fromSoc];
  if (!edges) return 0;
  const edge = edges.find((e) => e.toSoc === toSoc);
  return edge?.score ?? 0;
}

/**
 * Top-N roles a worker in fromSoc can transfer to, sorted by score.
 */
export function getTopTransfers(fromSoc: string, n: number = 10): TransferEdge[] {
  return (TRANSFERABILITY[fromSoc] || []).slice(0, n);
}
